styles:
.page-case .case-hero { padding-top: clamp(140px, 18vh, 220px); padding-bottom: clamp(30px, 5vw, 56px); }
.page-case .case-hero__eyebrow { display: flex; flex-wrap: wrap; gap: 10px 14px; align-items: center; margin-bottom: clamp(18px, 3vw, 30px); }
.page-case .case-hero__eyebrow .tag { font-family: var(--font-body); font-size: clamp(14px, 1.05vw, 16px); color: var(--red); border: 1px solid var(--line); border-radius: 999px; padding: 6px 16px; }
.page-case .case-hero__title { font-size: clamp(52px, 10vw, 148px); color: var(--grey-700); letter-spacing: -0.02em; line-height: 1; }
.page-case .case-meta { display: flex; flex-wrap: wrap; gap: 10px 28px; margin-top: clamp(22px, 3vw, 36px); padding-top: clamp(20px, 2.4vw, 28px); border-top: 1px solid var(--line); }
.page-case .case-meta__item { display: flex; flex-direction: column; gap: 4px; }
.page-case .case-meta__label { font-size: 13px; letter-spacing: .12em; text-transform: uppercase; color: var(--grey-500); }
.page-case .case-meta__val { font-family: var(--font-display); font-size: clamp(18px, 1.6vw, 22px); color: var(--grey-900); }

.page-case .case-cover { border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt); }
.page-case .case-cover img { width: 100%; height: clamp(240px, 46vw, 640px); object-fit: cover; }

.page-case .case-block { max-width: 1100px; }
.page-case .case-block + .case-block { margin-top: clamp(48px, 6vw, 90px); }
.page-case .case-block .eyebrow { margin-bottom: 14px; }
.page-case .case-block h2 { font-size: clamp(30px, 3.6vw, 56px); color: var(--grey-700); line-height: 1.05; margin-bottom: clamp(16px, 1.8vw, 26px); }
.page-case .case-block p { font-size: clamp(16px, 1.15vw, 19px); color: var(--grey-700); max-width: 68ch; }
.page-case .case-block p + p { margin-top: 16px; }

.page-case .case-steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: clamp(16px, 1.8vw, 26px); margin-top: clamp(24px, 3vw, 40px); }
.page-case .case-step { border: 1px solid var(--line); border-radius: var(--radius-lg); padding: clamp(24px, 2.2vw, 36px); display: flex; flex-direction: column; gap: 12px; transition: box-shadow .4s var(--ease), transform .4s var(--ease); }
.page-case .case-step:hover { box-shadow: 0 20px 50px rgba(0,0,0,.06); transform: translateY(-4px); }
.page-case .case-step__num { font-family: var(--font-display); font-size: clamp(38px, 3.4vw, 56px); color: var(--red); line-height: 1; }
.page-case .case-step h3 { font-size: clamp(20px, 1.6vw, 24px); color: var(--grey-900); }
.page-case .case-step p { font-size: clamp(15px, 1.05vw, 17px); color: var(--grey-700); }

.page-case .case-note { max-width: 1100px; margin-top: clamp(20px, 2.4vw, 30px); font-size: clamp(16px, 1.15vw, 19px); color: var(--grey-700); }
.page-case .case-note strong { color: var(--grey-900); font-weight: 400; }

.page-case .case-impact { list-style: none; display: grid; gap: 0; margin-top: clamp(20px, 2.4vw, 30px); max-width: 1000px; }
.page-case .case-impact li { display: flex; gap: clamp(18px, 2.4vw, 32px); align-items: baseline; padding: clamp(18px, 2vw, 28px) 0; border-top: 1px solid var(--line); font-size: clamp(17px, 1.35vw, 22px); color: var(--grey-700); }
.page-case .case-impact li:last-child { border-bottom: 1px solid var(--line); }
.page-case .case-impact li .n { font-family: var(--font-display); color: var(--red); font-size: clamp(22px, 2vw, 30px); flex-shrink: 0; }

.page-case .case-nav { display: flex; flex-wrap: wrap; gap: 18px; justify-content: space-between; align-items: center; margin-top: clamp(56px, 7vw, 100px); padding-top: clamp(28px, 3vw, 44px); border-top: 1px solid var(--line); }
.page-case .case-nav__back { display: inline-flex; align-items: center; gap: 12px; font-family: var(--font-display); font-size: clamp(20px, 2vw, 30px); color: var(--grey-900); transition: color .25s var(--ease); }
.page-case .case-nav__back:hover { color: var(--red); }
.page-case .case-nav__back .arrow { width: 44px; height: 44px; border-radius: 50%; border: 1.5px solid var(--red); color: var(--red); display: grid; place-items: center; transition: background .3s var(--ease), color .3s var(--ease); }
.page-case .case-nav__back:hover .arrow { background: var(--red); color: #fff; }
.page-case .case-nav__hint { font-size: 14px; color: var(--grey-500); letter-spacing: .08em; text-transform: uppercase; }

@media (max-width: 760px) {
  .page-case .case-steps { grid-template-columns: 1fr; }
  .page-case .case-cover img { height: clamp(220px, 60vw, 360px); }
}
